WITH latest AS (SELECT * FROM accounts QUALIFY ROW_NUMBER() OVER (PARTITION BY status ORDER BY opened_date DESC, id) = 1), kept AS (SELECT s.* FROM latest s WHERE NOT EXISTS (SELECT 1 FROM transactions ch WHERE ch.account_id = s.id AND ch.txn_time >= s.opened_date)), enriched AS (SELECT e.id, e.customer_id, e.account_type, d.signup_date, d.segment, d.email FROM kept e LEFT JOIN customers d ON e.customer_id = d.id), deduped AS (SELECT *, ROW_NUMBER() OVER (PARTITION BY segment, account_type ORDER BY signup_date DESC, id) AS dedup_rank FROM enriched QUALIFY dedup_rank = 1), with_last AS (SELECT s.id, s.customer_id, latest.txn_type, latest.transaction_amount FROM deduped s LEFT JOIN LATERAL (SELECT c.txn_type, c.amount AS transaction_amount FROM transactions c WHERE c.account_id = s.id ORDER BY c.amount DESC, c.id DESC LIMIT 1) latest ON TRUE), enriched_accounts AS (SELECT src.id, src.customer_id, src.txn_type, d.signup_date, d.name, d.segment FROM with_last src LEFT JOIN customers d ON src.customer_id = d.id) SELECT customer_id, COUNT(*) FILTER (WHERE txn_type = 'FEE') AS fee_rows, COUNT(*) AS event_count FROM enriched_accounts GROUP BY customer_id;
